class Solution {
public:
    bool validPartition(vector<int>& nums) {
        int n = nums.size();
        if (n < 2) return false;
        if (n == 2) return nums[0] == nums[1];

        // dp[i] = true iff prefix of length i is validly partitionable.
        // We only keep the last three values: prev3=dp[i-3], prev2=dp[i-2], prev1=dp[i-1].
        bool prev3 = true;                       // dp[0]
        bool prev2 = false;                      // dp[1] (single element never valid)
        bool prev1 = (nums[0] == nums[1]);       // dp[2]

        for (int i = 3; i <= n; ++i) {
            bool curr = false;
            // 2 equal elements ending at i-1
            if (nums[i - 2] == nums[i - 1] && prev2) curr = true;
            // 3 equal elements ending at i-1
            else if (nums[i - 3] == nums[i - 2] && nums[i - 2] == nums[i - 1] && prev3) curr = true;
            // 3 consecutive increasing elements ending at i-1
            else if (nums[i - 3] + 1 == nums[i - 2] && nums[i - 2] + 1 == nums[i - 1] && prev3) curr = true;

            prev3 = prev2;
            prev2 = prev1;
            prev1 = curr;
        }
        return prev1;
    }
};
